-- 105: 纵向项目 PDF 计划书解析、查重校验与批量导入
BEGIN;

-- 1. 纵向项目导入批次
CREATE TABLE IF NOT EXISTS "纵向项目导入批次" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "批次名称" varchar(200) NOT NULL,
    "来源类型" varchar(50) NOT NULL DEFAULT '国家自然科学基金',
    "状态" varchar(30) NOT NULL DEFAULT '待校验',
    "总文件数" integer NOT NULL DEFAULT 0,
    "解析成功数" integer NOT NULL DEFAULT 0,
    "解析失败数" integer NOT NULL DEFAULT 0,
    "导入成功数" integer NOT NULL DEFAULT 0,
    "导入人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_纵向导入批次_来源" CHECK ("来源类型" IN ('国家自然科学基金','省部级','其他','Excel')),
    CONSTRAINT "ck_纵向导入批次_状态" CHECK ("状态" IN ('解析中','待校验','已校验','已导入','已关闭'))
);

-- 2. 纵向项目导入明细
CREATE TABLE IF NOT EXISTS "纵向项目导入明细" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "批次编号" bigint NOT NULL REFERENCES "纵向项目导入批次"("编号") ON DELETE CASCADE,
    "源文件名" varchar(300) NOT NULL,
    "文件存储路径" varchar(2000) NOT NULL,
    "文件哈希" varchar(128) NOT NULL,
    "解析状态" varchar(30) NOT NULL DEFAULT '已解析',
    "文本摘要" varchar(4000),
    "解析字段" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "校验结果" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "校验状态" varchar(30) NOT NULL DEFAULT '待校验',
    "处理状态" varchar(30) NOT NULL DEFAULT '待处理',
    "导入纵向项目编号" integer REFERENCES "纵向项目立项"("编号") ON DELETE SET NULL,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_纵向导入明细_批次哈希" UNIQUE ("批次编号", "文件哈希"),
    CONSTRAINT "ck_纵向导入明细_解析状态" CHECK ("解析状态" IN ('已解析','解析失败','需人工')),
    CONSTRAINT "ck_纵向导入明细_校验状态" CHECK ("校验状态" IN ('待校验','通过','警告','失败')),
    CONSTRAINT "ck_纵向导入明细_处理状态" CHECK ("处理状态" IN ('待处理','已导入','已忽略'))
);
CREATE INDEX IF NOT EXISTS "ix_纵向导入明细_批次状态" ON "纵向项目导入明细" ("批次编号", "校验状态", "处理状态");

-- 权限配置
INSERT INTO "权限" ("编号", "上级编号", "名称", "路径", "类型", "备注")
VALUES (213, 2, '纵向项目导入', '科研办公/科研办公/纵向项目导入.html', TRUE, '国家自然科学基金等计划书 PDF 解析、批量校验与导入')
ON CONFLICT ("编号") DO UPDATE SET "名称"=EXCLUDED."名称", "路径"=EXCLUDED."路径", "备注"=EXCLUDED."备注";

INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", 213 FROM "角色" r
WHERE r."名称" IN ('系统管理员','科研管理员','科技办')
  AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=213);

UPDATE "系统迁移版本"
SET "版本"=105, "脚本"='105_vertical_project_pdf_import.sql',
    "检查摘要"='增加纵向项目PDF计划书解析批次、校验规则、明细记录与立项导入', "应用时间"=CURRENT_TIMESTAMP
WHERE "编号"=1;

COMMIT;
